def transform(grid):
    rows = len(grid)
    if rows == 0:
        return grid
    cols = len(grid[0])
    output = [row[:] for row in grid]

    # Background color (not the pattern color)
    background = grid[0][0] if grid else 0
    pattern_color = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != background and grid[r][c] not in [background]:
                pattern_color = grid[r][c]
                break
        if pattern_color:
            break

    if not pattern_color:
        return grid

    # Flood fill: background cells connected to edge remain
    # Enclosed background cells become the fillColor (which is 2 in demo)
    visited = [[False] * cols for _ in range(rows)]

    # Start flood from all edge cells
    from collections import deque
    queue = deque()

    for r in range(rows):
        if grid[r][0] == background:
            queue.append((r, 0))
            visited[r][0] = True
        if grid[r][cols-1] == background:
            queue.append((r, cols-1))
            visited[r][cols-1] = True

    for c in range(cols):
        if grid[0][c] == background and not visited[0][c]:
            queue.append((0, c))
            visited[0][c] = True
        if grid[rows-1][c] == background and not visited[rows-1][c]:
            queue.append((rows-1, c))
            visited[rows-1][c] = True

    fillColor = 2  # From the demo, background inside becomes 2

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if not visited[nr][nc] and grid[nr][nc] == background:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    # Cells NOT visited (inside) and NOT pattern color become fillColor
    for r in range(rows):
        for c in range(cols):
            if not visited[r][c] and grid[r][c] == background:
                output[r][c] = fillColor

    return output
